<style>
  :root {
    --cyan: #7fe9ff;
    --amber: #ffb24d;
    --ink: #04070d;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: var(--ink); }
  body {
    font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    color: #cfeeff;
  }
  #view { position: fixed; inset: 0; width: 100%; height: 100%; display: block; }
  /* vignette + faint scanlines */
  #veil {
    position: fixed; inset: 0; pointer-events: none;
    background:
      repeating-linear-gradient(0deg, rgba(127,233,255,0.028) 0 1px, transparent 1px 3px),
      radial-gradient(ellipse at 50% 55%, transparent 55%, rgba(2,5,10,0.55) 100%);
  }
  .hud { position: fixed; pointer-events: none; text-shadow: 0 0 8px rgba(127,233,255,0.25); }
  #top { top: 22px; left: 26px; }
  #top .title {
    font-size: 15px; letter-spacing: 0.34em; color: var(--cyan);
  }
  #top .title b { color: var(--amber); font-weight: 600; }
  #top .sub {
    margin-top: 6px; font-size: 10px; letter-spacing: 0.28em; color: rgba(207,238,255,0.5);
  }
  #panel {
    left: 26px; bottom: 24px; display: flex; flex-direction: column; gap: 10px;
    align-items: flex-start; pointer-events: none;
  }
  #panel button {
    pointer-events: auto;
    font: inherit; font-size: 11px; letter-spacing: 0.22em;
    color: #cfeeff; background: rgba(8,18,30,0.55);
    border: 1px solid rgba(127,233,255,0.32);
    padding: 10px 16px; cursor: pointer;
    backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
    transition: border-color .15s, background .15s, box-shadow .15s;
  }
  #panel button:hover { border-color: rgba(127,233,255,0.8); }
  #panel button.on {
    background: rgba(127,233,255,0.14); border-color: var(--cyan);
    box-shadow: 0 0 14px rgba(127,233,255,0.25), inset 0 0 12px rgba(127,233,255,0.12);
    color: #ffffff;
  }
  #panel button.warn.on {
    background: rgba(255,178,77,0.14); border-color: var(--amber);
    box-shadow: 0 0 14px rgba(255,178,77,0.25), inset 0 0 12px rgba(255,178,77,0.12);
  }
  #telemetry {
    margin-top: 4px; font-size: 10px; letter-spacing: 0.18em;
    color: rgba(207,238,255,0.55); line-height: 1.9;
  }
  #telemetry .amber { color: var(--amber); }
  #telemetry .cyan { color: var(--cyan); }
  #hint {
    right: 26px; bottom: 24px; text-align: right;
    font-size: 10px; letter-spacing: 0.22em; color: rgba(207,238,255,0.4);
    line-height: 2;
  }
  #corner {
    top: 22px; right: 26px; text-align: right;
    font-size: 10px; letter-spacing: 0.26em; color: rgba(255,178,77,0.75);
  }
  #corner .lamp {
    display: inline-block; width: 8px; height: 8px; border-radius: 50%;
    background: var(--amber); box-shadow: 0 0 10px var(--amber);
    margin-left: 8px; vertical-align: middle;
    animation: blink 1.3s steps(1) infinite;
  }
  @keyframes blink { 0%, 10% { opacity: 1; } 11%, 100% { opacity: 0.15; } }
</style>
</head>
<body>
  <canvas id="view"></canvas>

  <div class="hud" id="top">
    <div class="title">HANGAR BAY <b>07</b> — DRONE CONTROL</div>
    <div class="sub">SECTOR K-9 // NIGHT CYCLE // DECK PRESSURE NOMINAL</div>
  </div>

  <div class="hud" id="corner">
    CAUTION: ACTIVE FLIGHT DECK<span class="lamp"></span>
  </div>

  <div class="hud" id="panel">
    <button id="btnForm">FORMATION: PATROL SPREAD</button>
    <button id="btnCam">CAMERA: CINEMATIC PATH</button>
    <div id="telemetry">
      <div>DRONES <span class="cyan">10/10 LINKED</span></div>
      <div>RUNWAY <span class="cyan">EMISSIVE GRID LIVE</span></div>
      <div>BEACONS <span class="amber">SWEEP ACTIVE</span></div>
    </div>
  </div>

  <div class="hud" id="hint">
    DRAG — ORBIT &nbsp;·&nbsp; SCROLL — ZOOM<br>
    F — FORMATION &nbsp;·&nbsp; C — CINEMATIC
  </div>

  <div id="veil"></div>

  <script>
/*__THREE__*/
  </script>
  <script>
/*__APP__*/
