/* HANGAR BAY 07 — sci-fi hangar scene. Requires global THREE. */
(function () {
  'use strict';

  // ------------------------------------------------------------- renderer
  var canvas = document.getElementById('view');
  var renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.15;
  if ('outputColorSpace' in renderer && THREE.SRGBColorSpace) renderer.outputColorSpace = THREE.SRGBColorSpace;
  else if ('outputEncoding' in renderer && THREE.sRGBEncoding) renderer.outputEncoding = THREE.sRGBEncoding;

  var scene = new THREE.Scene();
  scene.background = new THREE.Color(0x04070d);
  scene.fog = new THREE.FogExp2(0x04070d, 0.018);

  var camera = new THREE.PerspectiveCamera(58, window.innerWidth / window.innerHeight, 0.1, 400);
  camera.position.set(11, 3.4, 42);

  // ------------------------------------------------------------- textures
  var maxAniso = renderer.capabilities.getMaxAnisotropy();

  function tex(w, h, draw) {
    var c = document.createElement('canvas');
    c.width = w; c.height = h;
    draw(c.getContext('2d'), w, h);
    var t = new THREE.CanvasTexture(c);
    t.anisotropy = maxAniso;
    return t;
  }

  var glowTex = tex(128, 128, function (ctx, w, h) {
    var g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
    g.addColorStop(0.00, 'rgba(255,255,255,1)');
    g.addColorStop(0.30, 'rgba(255,255,255,0.55)');
    g.addColorStop(0.65, 'rgba(255,255,255,0.14)');
    g.addColorStop(1.00, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });

  var wispTex = tex(256, 256, function (ctx, w, h) {
    ctx.clearRect(0, 0, w, h);
    for (var i = 0; i < 18; i++) {
      var x = Math.random() * w, y = Math.random() * h, r = 26 + Math.random() * 62;
      var g = ctx.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, 'rgba(255,255,255,0.16)');
      g.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = g;
      ctx.fillRect(x - r, y - r, r * 2, r * 2);
    }
  });
  wispTex.wrapS = wispTex.wrapT = THREE.RepeatWrapping;

  var shaftTex = tex(16, 128, function (ctx, w, h) {
    var g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, 'rgba(255,255,255,0.85)');
    g.addColorStop(0.55, 'rgba(255,255,255,0.28)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });

  var floorTex = tex(512, 512, function (ctx, w, h) {
    ctx.fillStyle = '#0b1018';
    ctx.fillRect(0, 0, w, h);
    for (var i = 0; i < 2600; i++) {
      ctx.fillStyle = Math.random() < 0.5 ? 'rgba(150,185,215,0.05)' : 'rgba(0,0,0,0.16)';
      ctx.fillRect(Math.random() * w, Math.random() * h, 2, 2);
    }
    ctx.strokeStyle = 'rgba(125,165,195,0.10)';
    ctx.lineWidth = 2;
    for (var p = 0; p <= w; p += 64) {
      ctx.beginPath(); ctx.moveTo(p, 0); ctx.lineTo(p, h); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, p); ctx.lineTo(w, p); ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.lineWidth = 4;
    for (var q = 0; q <= w; q += 256) {
      ctx.beginPath(); ctx.moveTo(q, 0); ctx.lineTo(q, h); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, q); ctx.lineTo(w, q); ctx.stroke();
    }
  });
  floorTex.wrapS = floorTex.wrapT = THREE.RepeatWrapping;
  floorTex.repeat.set(6, 17);

  function dashTexture() {
    var t = tex(32, 256, function (ctx, w, h) {
      ctx.fillStyle = '#03080e';
      ctx.fillRect(0, 0, w, h);
      for (var i = 0; i < 40; i++) {
        ctx.fillStyle = 'rgba(70,120,150,0.22)';
        ctx.fillRect(Math.random() * w, Math.random() * h, 2, 2);
      }
      ctx.fillStyle = '#7fe9ff';
      ctx.fillRect(5, 76, 22, 104);
      ctx.fillStyle = '#eaffff';
      ctx.fillRect(10, 88, 12, 80);
    });
    t.wrapS = THREE.ClampToEdgeWrapping;
    t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(1, 24);
    return t;
  }

  var stripeTex = tex(128, 64, function (ctx, w, h) {
    ctx.fillStyle = '#0d0d0d';
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = '#c9a227';
    for (var i = -h; i < w + h; i += 32) {
      ctx.beginPath();
      ctx.moveTo(i, 0); ctx.lineTo(i + 15, 0);
      ctx.lineTo(i + 15 - h, h); ctx.lineTo(i - h, h);
      ctx.closePath(); ctx.fill();
    }
  });
  stripeTex.wrapS = stripeTex.wrapT = THREE.RepeatWrapping;

  var doorTex = tex(64, 256, function (ctx, w, h) {
    var g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#08131f');
    g.addColorStop(0.55, '#12384f');
    g.addColorStop(1, '#8ef0ff');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });

  // ------------------------------------------------------------ materials
  var hullMat = new THREE.MeshStandardMaterial({ color: 0x232c3b, metalness: 0.55, roughness: 0.45 });
  var wallMat = new THREE.MeshStandardMaterial({ map: floorTex, color: 0x59646f, metalness: 0.35, roughness: 0.8 });
  var darkMat = new THREE.MeshStandardMaterial({ color: 0x141a24, metalness: 0.6, roughness: 0.5 });
  var stripeMat = new THREE.MeshStandardMaterial({ map: stripeTex, emissive: 0x2a1c04, metalness: 0.2, roughness: 0.7 });

  // ---------------------------------------------------------- hangar shell
  var shell = new THREE.Group();
  scene.add(shell);

  function slab(w, h, d, x, y, z, mat) {
    var m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat || hullMat);
    m.position.set(x, y, z);
    shell.add(m);
    return m;
  }

  var floor = new THREE.Mesh(new THREE.PlaneGeometry(45.8, 126), new THREE.MeshStandardMaterial({
    map: floorTex, color: 0x6a7683, metalness: 0.45, roughness: 0.6
  }));
  floor.rotation.x = -Math.PI / 2;
  shell.add(floor);

  slab(1.4, 16, 126, -22.2, 8, 0, wallMat);
  slab(1.4, 16, 126, 22.2, 8, 0, wallMat);
  slab(45.8, 1.2, 126, 0, 16.6, 0, darkMat);

  // ribs + hazard-striped kick plates
  for (var rz = -52.5, ri = 0; rz <= 52.5; rz += 15, ri++) {
    slab(2.0, 16, 1.4, -21.4, 8, rz);
    slab(2.0, 16, 1.4, 21.4, 8, rz);
    slab(44.6, 0.7, 0.7, 0, 15.4, rz);
    var kpL = slab(2.2, 3.2, 1.7, -21.3, 1.6, rz, stripeMat);
    var kpR = slab(2.2, 3.2, 1.7, 21.3, 1.6, rz, stripeMat);
    kpL.material = kpR.material = stripeMat;
    if (ri % 2 === 0) {
      // wall-mounted caution bars (blinking, animated below)
      cautionBars.push(makeCautionBar(-21.3, 10.5, rz + 3.5, Math.PI / 2));
      cautionBars.push(makeCautionBar(21.3, 10.5, rz + 3.5, -Math.PI / 2));
    }
  }

  // back wall (z = -62) with door opening 22w x 12h
  slab(11.4, 16, 1.4, -16.3, 8, -62.3, wallMat);
  slab(11.4, 16, 1.4, 16.3, 8, -62.3, wallMat);
  slab(22.6, 4.2, 1.4, 0, 14.1, -62.3, wallMat);
  // door frame hazard trim
  stripeTex.repeat.set(8, 1);
  var fT = slab(23.4, 1.0, 1.8, 0, 12.4, -62.2, stripeMat);
  var fB = slab(23.4, 0.7, 1.8, 0, 0.35, -62.2, stripeMat);
  var fL = slab(1.0, 12.4, 1.8, -11.4, 6.2, -62.2, stripeMat);
  var fR = slab(1.0, 12.4, 1.8, 11.4, 6.2, -62.2, stripeMat);
  void fT; void fB; void fL; void fR;

  // exterior mist seen through the open door
  var doorGlow = new THREE.Mesh(new THREE.PlaneGeometry(40, 22), new THREE.MeshBasicMaterial({
    map: doorTex, fog: false, toneMapped: true
  }));
  doorGlow.position.set(0, 8, -66.5);
  shell.add(doorGlow);

  // front wall (z = +62) with control-room windows
  slab(45.8, 16, 1.4, 0, 8, 62.3, wallMat);
  slab(20, 1.2, 3.4, 0, 5.6, 60.8, darkMat); // catwalk
  for (var wi = -2; wi <= 2; wi++) {
    var win = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 1.5), new THREE.MeshBasicMaterial({ color: 0x5fc8e8, fog: false }));
    win.position.set(wi * 4.2, 9.2, 61.5);
    win.rotation.y = Math.PI;
    shell.add(win);
    var winGlow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: 0x5fc8e8, blending: THREE.AdditiveBlending,
      transparent: true, opacity: 0.28, depthWrite: false, fog: false
    }));
    winGlow.position.set(wi * 4.2, 9.2, 60.8);
    winGlow.scale.set(5, 3, 1);
    shell.add(winGlow);
  }

  // --------------------------------------------------------- ceiling lights
  var fixtureMat = new THREE.MeshBasicMaterial({ color: 0xcfe9ff, fog: true });
  for (var fz = -40; fz <= 40; fz += 20) {
    slab(24, 0.3, 1.0, 0, 15.3, fz, fixtureMat);
    var pool = new THREE.Mesh(new THREE.PlaneGeometry(26, 24), new THREE.MeshBasicMaterial({
      map: glowTex, color: 0x9fd4ff, blending: THREE.AdditiveBlending,
      transparent: true, opacity: 0.05, depthWrite: false, fog: false
    }));
    pool.rotation.x = -Math.PI / 2;
    pool.position.set(0, 0.02, fz);
    shell.add(pool);
    // crossed light shafts under fixture
    for (var s = 0; s < 2; s++) {
      var shaft = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 13.4), new THREE.MeshBasicMaterial({
        map: shaftTex, color: 0xbfe4ff, blending: THREE.AdditiveBlending,
        transparent: true, opacity: 0.05, depthWrite: false, side: THREE.DoubleSide, fog: false
      }));
      shaft.position.set(0, 8.4, fz);
      shaft.rotation.y = s * Math.PI / 2;
      shell.add(shaft);
    }
  }

  // slanted light shafts pouring in through the door
  var doorShaftMat = new THREE.MeshBasicMaterial({
    map: shaftTex, color: 0x8fe4ff, blending: THREE.AdditiveBlending,
    transparent: true, opacity: 0.05, depthWrite: false, side: THREE.DoubleSide, fog: false
  });
  for (var ds = 0; ds < 2; ds++) {
    var dsh = new THREE.Mesh(new THREE.PlaneGeometry(22, 31), doorShaftMat);
    dsh.position.set(ds ? 0.9 : -0.9, 6, ds ? -47.8 : -46.2);
    dsh.rotation.set(-1.165, ds ? 0.05 : -0.05, 0);
    shell.add(dsh);
  }

  // ------------------------------------------------------------ runway grid
  function addStrip(x) {
    var texA = dashTexture();
    var lane = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 118), new THREE.MeshBasicMaterial({
      map: texA, color: 0xbff6ff, fog: true
    }));
    lane.rotation.x = -Math.PI / 2;
    lane.position.set(x, 0.03, 0);
    scene.add(lane);
    for (var e = -1; e <= 1; e += 2) {
      var edge = new THREE.Mesh(new THREE.PlaneGeometry(0.07, 118), new THREE.MeshBasicMaterial({
        color: 0x7fe9ff, fog: true
      }));
      edge.rotation.x = -Math.PI / 2;
      edge.position.set(x + e * 0.62, 0.03, 0);
      scene.add(edge);
    }
    return texA;
  }
  var dashA = addStrip(-4.0);
  var dashB = addStrip(4.0);

  // runway edge lights — traveling wave, instanced
  var edgeCount = 84;
  var edgeGeo = new THREE.BoxGeometry(0.16, 0.1, 0.16);
  var edgeMesh = new THREE.InstancedMesh(edgeGeo, new THREE.MeshBasicMaterial({ color: 0xffffff, fog: true }), edgeCount);
  var dummy = new THREE.Object3D();
  var edgeZ = new Float32Array(edgeCount);
  var ei = 0;
  for (var ex = -1; ex <= 1; ex += 2) {
    for (var ez = -58; ez <= 58 && ei < edgeCount; ez += 2.8) {
      dummy.position.set(ex * 5.4, 0.05, ez);
      dummy.updateMatrix();
      edgeMesh.setMatrixAt(ei, dummy.matrix);
      edgeZ[ei] = ez;
      ei++;
    }
  }
  while (ei < edgeCount) { // pad any unused slots far below the deck
    dummy.position.set(0, -50, 0);
    dummy.updateMatrix();
    edgeMesh.setMatrixAt(ei, dummy.matrix);
    edgeZ[ei] = 999;
    ei++;
  }
  scene.add(edgeMesh);
  var edgeColor = new THREE.Color();

  // ---------------------------------------------------------- warning lights
  var cautionBars = [];
  var barMatProto = new THREE.MeshBasicMaterial({ color: 0xffb24d, fog: true });
  function makeCautionBar(x, y, z, ry) {
    var m = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.28, 0.12), barMatProto.clone());
    m.position.set(x, y, z);
    m.rotation.y = ry;
    scene.add(m);
    var spr = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: 0xffb24d, blending: THREE.AdditiveBlending,
      transparent: true, opacity: 0.3, depthWrite: false, fog: false
    }));
    spr.position.set(x, y, z);
    spr.scale.set(4.2, 1.6, 1);
    scene.add(spr);
    var bar = { mat: m.material, spr: spr };
    cautionBars.push(bar);
    return bar;
  }

  // rotating sweep beacons on the walls
  var beacons = [];
  function makeBeacon(x, y, z, ry) {
    var g = new THREE.Group();
    g.position.set(x, y, z);
    var domeMat = new THREE.MeshBasicMaterial({ color: 0xff8a2a, fog: true });
    var dome = new THREE.Mesh(new THREE.SphereGeometry(0.42, 14, 10, 0, Math.PI * 2, 0, Math.PI / 2), domeMat);
    g.add(dome);
    var base = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.55, 0.3, 12), darkMat);
    base.position.y = -0.15;
    g.add(base);
    var pivot = new THREE.Group();
    var coneMat = new THREE.MeshBasicMaterial({
      color: 0xffa64d, blending: THREE.AdditiveBlending, transparent: true,
      opacity: 0.06, depthWrite: false, side: THREE.DoubleSide, fog: false
    });
    var cone = new THREE.Mesh(new THREE.ConeGeometry(2.6, 7.5, 18, 1, true), coneMat);
    cone.position.set(0, 0.2, 3.6);
    cone.rotation.x = Math.PI / 2.55;
    pivot.add(cone);
    g.add(pivot);
    var halo = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: 0xffa64d, blending: THREE.AdditiveBlending,
      transparent: true, opacity: 0.4, depthWrite: false, fog: false
    }));
    halo.scale.set(3.2, 3.2, 1);
    g.add(halo);
    g.rotation.y = ry;
    scene.add(g);
    var b = { pivot: pivot, domeMat: domeMat, coneMat: coneMat, halo: halo, phase: Math.random() * 6.28 };
    beacons.push(b);
    return b;
  }
  makeBeacon(-20.6, 11.8, -40, Math.PI / 2);
  makeBeacon(20.6, 11.8, -40, -Math.PI / 2);
  makeBeacon(-20.6, 11.8, 20, Math.PI / 2);
  makeBeacon(20.6, 11.8, 20, -Math.PI / 2);

  // red strobes flanking the door
  var strobes = [];
  for (var st = -1; st <= 1; st += 2) {
    var sMat = new THREE.MeshBasicMaterial({ color: 0xff2a2a, fog: true });
    var sMesh = new THREE.Mesh(new THREE.SphereGeometry(0.24, 10, 8), sMat);
    sMesh.position.set(st * 12.4, 11.6, -61.2);
    scene.add(sMesh);
    var sGlow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: 0xff3a2a, blending: THREE.AdditiveBlending,
      transparent: true, opacity: 0.5, depthWrite: false, fog: false
    }));
    sGlow.position.copy(sMesh.position);
    sGlow.scale.set(3, 3, 1);
    scene.add(sGlow);
    strobes.push({ mat: sMat, glow: sGlow });
  }

  // ---------------------------------------------------------------- lights
  scene.add(new THREE.AmbientLight(0x25314a, 0.85));
  scene.add(new THREE.HemisphereLight(0x3a4a66, 0x0a0d14, 0.55));
  var keyLight = new THREE.DirectionalLight(0x88cfff, 0.5);
  keyLight.position.set(0, 18, -80);
  scene.add(keyLight);
  scene.add(new THREE.PointLight(0x9fd8ff, 0.6, 60).translateY(0)); // placeholder replaced below
  scene.children.pop();
  var p1 = new THREE.PointLight(0x9fd8ff, 0.6, 60, 2); p1.position.set(0, 12, -24); scene.add(p1);
  var p2 = new THREE.PointLight(0x9fd8ff, 0.5, 60, 2); p2.position.set(0, 12, 16); scene.add(p2);
  var warnLight = new THREE.PointLight(0xff8a2a, 0.0, 34, 2); warnLight.position.set(0, 11, -40); scene.add(warnLight);

  // -------------------------------------------------------------- drones
  var PATROL = [
    [-8.5, 5.0, -26], [7.5, 6.2, -20], [-5.5, 4.4, -10], [9.0, 5.4, -2], [-9.5, 6.6, 6],
    [4.5, 4.8, 14], [-6.5, 5.8, 22], [8.5, 4.6, 28], [-2.5, 7.2, -34], [2.5, 5.2, 34]
  ];
  var VEE = [
    [0, 6.2, -16],
    [-3.0, 5.9, -8], [3.0, 5.9, -8],
    [-5.8, 5.6, 0], [5.8, 5.6, 0],
    [-8.6, 5.3, 8], [8.6, 5.3, 8],
    [-11.2, 5.0, 16], [11.2, 5.0, 16],
    [0, 7.4, 22]
  ];

  var hullDroneMat = new THREE.MeshStandardMaterial({ color: 0x1b2331, metalness: 0.65, roughness: 0.35 });
  var glassMat = new THREE.MeshStandardMaterial({ color: 0x0a1420, metalness: 0.9, roughness: 0.12 });
  var rotorMat = new THREE.MeshBasicMaterial({
    color: 0x9fe8ff, blending: THREE.AdditiveBlending, transparent: true,
    opacity: 0.16, side: THREE.DoubleSide, depthWrite: false, fog: false
  });
  var shadowMat = new THREE.MeshBasicMaterial({
    map: glowTex, color: 0x000000, transparent: true, opacity: 0.45, depthWrite: false, fog: false
  });

  function makeDrone(accent) {
    var g = new THREE.Group();
    var hull = new THREE.Mesh(new THREE.OctahedronGeometry(0.85, 0), hullDroneMat);
    hull.scale.set(1, 0.4, 1.35);
    g.add(hull);
    var canopy = new THREE.Mesh(new THREE.SphereGeometry(0.2, 12, 10), glassMat);
    canopy.position.set(0, 0.1, -0.6);
    canopy.scale.set(1, 0.7, 1.5);
    g.add(canopy);
    var eye = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.05, 0.03), new THREE.MeshBasicMaterial({ color: accent, fog: false }));
    eye.position.set(0, 0.08, -0.9);
    g.add(eye);

    var spin = [];
    for (var k = 0; k < 4; k++) {
      var ang = Math.PI / 4 + k * (Math.PI / 2);
      var dx = Math.sin(ang), dz = Math.cos(ang);
      var arm = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.05, 1.0), hullDroneMat);
      arm.position.set(dx * 0.55, 0, dz * 0.55);
      arm.rotation.y = ang;
      g.add(arm);
      var nac = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.17, 0.16, 10), hullDroneMat);
      nac.position.set(dx * 1.02, 0.02, dz * 1.02);
      g.add(nac);
      var disc = new THREE.Mesh(new THREE.CircleGeometry(0.34, 18), rotorMat);
      disc.rotation.x = -Math.PI / 2;
      disc.position.set(dx * 1.02, 0.12, dz * 1.02);
      g.add(disc);
      spin.push({ m: disc, dir: k % 2 ? -1 : 1 });
    }

    var ring = new THREE.Mesh(new THREE.TorusGeometry(0.52, 0.045, 8, 26), new THREE.MeshBasicMaterial({ color: accent, fog: true }));
    ring.rotation.x = Math.PI / 2;
    ring.position.y = -0.3;
    g.add(ring);

    var glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: accent, blending: THREE.AdditiveBlending,
      transparent: true, opacity: 0.4, depthWrite: false, fog: false
    }));
    glow.position.y = -0.45;
    glow.scale.set(2.4, 2.4, 1);
    g.add(glow);

    var shadow = new THREE.Mesh(new THREE.PlaneGeometry(2.8, 2.8), shadowMat);
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.y = 0.035;
    scene.add(shadow);

    scene.add(g);
    return {
      group: g, spin: spin, shadow: shadow,
      pos: new THREE.Vector3(PATROL[0][0], PATROL[0][1], PATROL[0][2]),
      target: new THREE.Vector3(), phase: Math.random() * 6.28
    };
  }

  var ACCENTS = [0xffa340, 0x51e6ff, 0x51e6ff, 0x51e6ff, 0x51e6ff, 0x51e6ff, 0x51e6ff, 0x51e6ff, 0x51e6ff, 0x51e6ff];
  var drones = [];
  for (var di = 0; di < 10; di++) {
    var d = makeDrone(ACCENTS[di]);
    d.pos.set(PATROL[di][0], PATROL[di][1], PATROL[di][2]);
    d.idx = di;
    drones.push(d);
  }

  // ------------------------------------------------------------- fog planes
  var fogPlanes = [];
  var fogMatBase = new THREE.MeshBasicMaterial({
    map: wispTex, color: 0x9fc4de, transparent: true, opacity: 0.07,
    depthWrite: false, fog: true, side: THREE.DoubleSide
  });
  for (var fp = 0; fp < 16; fp++) {
    var fm = new THREE.Mesh(new THREE.PlaneGeometry(24 + Math.random() * 16, 11 + Math.random() * 8), fogMatBase.clone());
    fm.material.opacity = 0.04 + Math.random() * 0.06;
    fm.material.map = wispTex.clone();
    fm.material.map.needsUpdate = true;
    fm.material.map.wrapS = fm.material.map.wrapT = THREE.RepeatWrapping;
    fm.material.map.repeat.set(1.5, 1);
    var base = new THREE.Vector3(
      (Math.random() * 2 - 1) * 15,
      1.5 + Math.random() * 6,
      -55 + Math.random() * 110
    );
    fm.position.copy(base);
    scene.add(fm);
    fogPlanes.push({ mesh: fm, base: base, phase: Math.random() * 6.28 });
  }

  // ground mist sheets
  var mistSheets = [];
  for (var ms = 0; ms < 3; ms++) {
    var mt = wispTex.clone();
    mt.needsUpdate = true;
    mt.wrapS = mt.wrapT = THREE.RepeatWrapping;
    mt.repeat.set(3, 2);
    var sheet = new THREE.Mesh(new THREE.PlaneGeometry(46, 34), new THREE.MeshBasicMaterial({
      map: mt, color: 0x86b6d8, blending: THREE.AdditiveBlending, transparent: true,
      opacity: 0.05, depthWrite: false, fog: false, side: THREE.DoubleSide
    }));
    sheet.rotation.x = -Math.PI / 2;
    sheet.position.set(0, 0.4 + ms * 0.9, -34 + ms * 34);
    scene.add(sheet);
    mistSheets.push({ mesh: sheet, tex: mt, phase: ms * 2.1 });
  }

  // --------------------------------------------------------- camera rig
  var state = { cinematic: true, formation: 'patrol' };

  var cinePath = new THREE.CatmullRomCurve3([
    new THREE.Vector3(11, 3.4, 42), new THREE.Vector3(-9, 4.2, 24),
    new THREE.Vector3(-4, 5.0, 2), new THREE.Vector3(7, 6.0, -18),
    new THREE.Vector3(0, 8.5, -38), new THREE.Vector3(-12, 10.5, -14),
    new THREE.Vector3(-14, 7.5, 14), new THREE.Vector3(-2, 4.0, 34)
  ], true, 'catmullrom', 0.5);
  var lookPath = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, 5, 4), new THREE.Vector3(0, 5, -8),
    new THREE.Vector3(0, 6, -18), new THREE.Vector3(0, 6, -30),
    new THREE.Vector3(0, 6, -34), new THREE.Vector3(0, 6, -8),
    new THREE.Vector3(0, 5, 8), new THREE.Vector3(0, 5, 12)
  ], true, 'catmullrom', 0.5);
  var cineT = 0;
  var smoothLook = lookPath.getPointAt(0).clone();

  var orbit = {
    target: new THREE.Vector3(0, 5, -4),
    theta: 0.22, phi: 1.2, radius: 42,
    dTheta: 0.22, dPhi: 1.2, dRadius: 42,
    dragging: false, px: 0, py: 0
  };
  var orbitPos = new THREE.Vector3();

  canvas.addEventListener('pointerdown', function (e) {
    orbit.dragging = true; orbit.px = e.clientX; orbit.py = e.clientY;
    canvas.setPointerCapture(e.pointerId);
  });
  canvas.addEventListener('pointermove', function (e) {
    if (!orbit.dragging) return;
    orbit.dTheta -= (e.clientX - orbit.px) * 0.005;
    orbit.dPhi = Math.min(1.5, Math.max(0.25, orbit.dPhi - (e.clientY - orbit.py) * 0.004));
    orbit.px = e.clientX; orbit.py = e.clientY;
  });
  canvas.addEventListener('pointerup', function () { orbit.dragging = false; });
  canvas.addEventListener('pointercancel', function () { orbit.dragging = false; });
  canvas.addEventListener('wheel', function (e) {
    e.preventDefault();
    orbit.dRadius = Math.min(85, Math.max(14, orbit.dRadius + e.deltaY * 0.03));
  }, { passive: false });

  // ------------------------------------------------------------------ UI
  var btnForm = document.getElementById('btnForm');
  var btnCam = document.getElementById('btnCam');

  function syncUI() {
    btnForm.textContent = 'FORMATION: ' + (state.formation === 'vee' ? 'VEE ASSEMBLY' : 'PATROL SPREAD');
    btnForm.classList.toggle('on', state.formation === 'vee');
    btnCam.textContent = 'CAMERA: ' + (state.cinematic ? 'CINEMATIC PATH' : 'MANUAL ORBIT');
    btnCam.classList.toggle('on', state.cinematic);
  }
  function toggleFormation() {
    state.formation = state.formation === 'vee' ? 'patrol' : 'vee';
    syncUI();
  }
  function toggleCinematic() {
    state.cinematic = !state.cinematic;
    syncUI();
  }
  btnForm.addEventListener('click', toggleFormation);
  btnCam.addEventListener('click', toggleCinematic);
  window.addEventListener('keydown', function (e) {
    var k = e.key.toLowerCase();
    if (k === 'f') toggleFormation();
    else if (k === 'c') toggleCinematic();
  });
  syncUI();

  // -------------------------------------------------------------- the loop
  var clock = new THREE.Clock();
  var tmp = new THREE.Vector3();

  function animate() {
    requestAnimationFrame(animate);
    var dt = Math.min(clock.getDelta(), 0.05);
    var t = clock.elapsedTime;

    // runway: scrolling dashes + traveling edge-light wave
    dashA.offset.y = -t * 0.35;
    dashB.offset.y = t * 0.35;
    for (var i = 0; i < edgeCount; i++) {
      var z = edgeZ[i];
      var pulse = z > 900 ? 0 : 0.25 + 0.75 * Math.pow(0.5 + 0.5 * Math.sin(z * 0.18 - t * 4.2), 3);
      edgeColor.setRGB(0.5 * pulse, 0.91 * pulse, 1.0 * pulse);
      edgeMesh.setColorAt(i, edgeColor);
    }
    edgeMesh.instanceColor.needsUpdate = true;

    // drones: damped formation swap + hover noise
    var tight = state.formation === 'vee' ? 0.35 : 1;
    var table = state.formation === 'vee' ? VEE : PATROL;
    for (var n = 0; n < drones.length; n++) {
      var dr = drones[n];
      var tgt = table[dr.idx];
      dr.target.set(tgt[0], tgt[1], tgt[2]);
      dr.pos.lerp(dr.target, 1 - Math.exp(-dt * 2.1));
      var bob = Math.sin(t * 1.15 + dr.phase) * 0.32 * tight;
      var sx = Math.sin(t * 0.6 + dr.phase * 1.7) * 0.22 * tight;
      var sz = Math.cos(t * 0.47 + dr.phase * 1.3) * 0.18 * tight;
      dr.group.position.set(dr.pos.x + sx, dr.pos.y + bob, dr.pos.z + sz);
      dr.group.rotation.z = Math.sin(t * 0.9 + dr.phase) * 0.055;
      dr.group.rotation.x = Math.cos(t * 0.7 + dr.phase) * 0.05;
      dr.group.rotation.y = Math.sin(t * 0.33 + dr.phase) * 0.18 * tight;
      for (var s2 = 0; s2 < dr.spin.length; s2++) {
        dr.spin[s2].m.rotation.z += dt * 40 * dr.spin[s2].dir;
      }
      dr.shadow.position.set(dr.pos.x + sx, 0.035, dr.pos.z + sz);
      var sh = 2.6 - bob * 0.2;
      dr.shadow.scale.set(sh / 2.8, sh / 2.8, 1);
    }

    // warning beacons: rotating sweep + breathing glow
    for (var b2 = 0; b2 < beacons.length; b2++) {
      var bc = beacons[b2];
      bc.pivot.rotation.y += dt * 1.7;
      var bl = 0.35 + 0.65 * Math.pow(0.5 + 0.5 * Math.sin(t * 2.2 + bc.phase), 2);
      bc.domeMat.color.setRGB(1.0 * bl, 0.54 * bl, 0.16 * bl);
      bc.coneMat.opacity = 0.03 + 0.07 * bl;
      bc.halo.material.opacity = 0.15 + 0.4 * bl;
    }

    // door strobes: hard blink
    var strobe = (t % 1.3) < 0.13 ? 1 : 0.05;
    for (var s3 = 0; s3 < strobes.length; s3++) {
      strobes[s3].mat.color.setRGB(1.0 * strobe, 0.16 * strobe, 0.1 * strobe);
      strobes[s3].glow.material.opacity = 0.55 * strobe;
    }

    // wall caution bars: alternating chase + scrolling hazard trim
    for (var c2 = 0; c2 < cautionBars.length; c2++) {
      var cb = cautionBars[c2];
      var chase = 0.18 + 0.82 * Math.pow(0.5 + 0.5 * Math.sin(t * 2.6 - c2 * 0.9), 3);
      cb.mat.color.setRGB(1.0 * chase, 0.7 * chase, 0.3 * chase);
      cb.spr.material.opacity = 0.1 + 0.3 * chase;
    }
    stripeTex.offset.x = t * 0.04;
    warnLight.intensity = 0.25 + 0.55 * Math.pow(0.5 + 0.5 * Math.sin(t * 2.2), 2);

    // volumetric-style fog: drifting billboards + scrolling ground mist
    for (var f2 = 0; f2 < fogPlanes.length; f2++) {
      var fpl = fogPlanes[f2];
      var m = fpl.mesh;
      m.position.set(
        fpl.base.x + Math.sin(t * 0.05 + fpl.phase) * 2.2,
        fpl.base.y + Math.sin(t * 0.07 + fpl.phase * 1.3) * 0.4,
        fpl.base.z + Math.cos(t * 0.04 + fpl.phase) * 1.8
      );
      m.quaternion.copy(camera.quaternion);
      m.rotateZ(Math.sin(t * 0.06 + fpl.phase) * 0.12);
      m.material.map.offset.x = t * 0.004 * (f2 % 2 ? 1 : -1);
    }
    for (var m2 = 0; m2 < mistSheets.length; m2++) {
      mistSheets[m2].tex.offset.y = t * 0.008 * (m2 % 2 ? 1 : -1);
      mistSheets[m2].tex.offset.x = t * 0.003;
    }

    // camera: cinematic spline vs damped manual orbit
    var damp = 1 - Math.exp(-dt * 2.6);
    if (state.cinematic) {
      cineT = (cineT + dt / 42) % 1;
      tmp.copy(cinePath.getPointAt(cineT));
      camera.position.lerp(tmp, damp);
      smoothLook.lerp(lookPath.getPointAt(cineT), 1 - Math.exp(-dt * 3.2));
      camera.lookAt(smoothLook);
    } else {
      orbit.theta += (orbit.dTheta - orbit.theta) * (1 - Math.exp(-dt * 8));
      orbit.phi += (orbit.dPhi - orbit.phi) * (1 - Math.exp(-dt * 8));
      orbit.radius += (orbit.dRadius - orbit.radius) * (1 - Math.exp(-dt * 5));
      var sp = Math.sin(orbit.phi), cp = Math.cos(orbit.phi);
      orbitPos.set(
        orbit.target.x + orbit.radius * sp * Math.sin(orbit.theta),
        orbit.target.y + orbit.radius * cp,
        orbit.target.z + orbit.radius * sp * Math.cos(orbit.theta)
      );
      camera.position.lerp(orbitPos, damp);
      smoothLook.lerp(orbit.target, 1 - Math.exp(-dt * 3.2));
      camera.lookAt(smoothLook);
    }

    renderer.render(scene, camera);
  }
  animate();

  window.addEventListener('resize', function () {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });
})();

