import numpy as np
from PIL import Image

def load(path):
    return np.asarray(Image.open(path).convert('RGB'), dtype=np.int16)

def stats(path):
    a = load(path)
    r, g, b = a[..., 0], a[..., 1], a[..., 2]
    luma = (0.299*r + 0.587*g + 0.114*b)
    cyan = ((b > 120) & (b > r + 30) & (g > r + 20)).sum()
    amber = ((r > 140) & (r > b + 60) & (g > r*0.4) & (g < r*0.9)).sum()
    red = ((r > 110) & (r > g + 50) & (r > b + 50)).sum()
    return {
        'mean_luma': round(float(luma.mean()), 2),
        'lit_frac': round(float((luma > 30).mean()), 4),
        'bright_frac': round(float((luma > 140).mean()), 4),
        'cyan_px': int(cyan), 'amber_px': int(amber), 'red_px': int(red),
    }

def diff(p1, p2):
    a, b = load(p1).mean(2), load(p2).mean(2)
    d = np.abs(a - b)
    return {'mean_abs_diff': round(float(d.mean()), 3),
            'changed_frac': round(float((d > 8).mean()), 4)}

shot1 = '.openchamber/screenshots/screenshot-1790036108472-hangar-initial-cinematic.jpg'
