{"language": "py", "title": "Formation + warning-light analysis", "code": "import numpy as np
from collections import deque

f4 = '.openchamber/screenshots/screenshot-1790036220458-hangar-manual-orbit.jpg'   # vee
f5 = '.openchamber/screenshots/screenshot-1790036288499-hangar-spread-after-switch.jpg' # spread (toggled)
f6 = '.openchamber/screenshots/screenshot-1790036307812-hangar-idle-baseline.jpg'  # idle control
frames = {'f1': f1, 'f2': f2, 'f3': f3, 'f4': f4, 'f5': f5, 'f6': f6}

def lum(p):
    a = load(p)
    return 0.299*a[..., 0] + 0.587*a[..., 1] + 0.114*a[..., 2]

def to_cells(mask, s=8, frac=0.25):
    h, w = mask.shape
    return (mask[:h//s*s, :w//s*s].reshape(h//s, s, w//s, s).mean(axis=(1, 3)) > frac)

def clusters(cellmask):
    seen = np.zeros_like(cellmask, bool)
    out = []
    ys, xs = np.nonzero(cellmask)
    for y0, x0 in zip(ys, xs):
        if seen[y0, x0]:
            continue
        q = deque([(y0, x0)]); seen[y0, x0] = True; size = 0
        while q:
            y, x = q.popleft(); size += 1
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < cellmask.shape[0] and 0 <= nx < cellmask.shape[1] \
                       and cellmask[ny, nx] and not seen[ny, nx]:
                        seen[ny, nx] = True; q.append((ny, nx))
        out.append(size)
    return sorted(out, reverse=True)

def dilate(mask, r):
    out = mask.copy()
    for dy in range(-r, r+1):
        for dx in range(-r, r+1):
            out |= np.roll(np.roll(mask, dy, 0), dx, 1)
    return out

L4, L5, L6 = lum(f4), lum(f5), lum(f6)
d_move = np.abs(L4 - L5) > 25      # across formation switch (68s gap)
d_idle = np.abs(L5 - L6) > 25      # idle control (19s gap)

excess = d_move & ~dilate(d_idle, 4)
cl_sw = clusters(to_cells(d_move))
cl_ex = clusters(to_cells(excess))
cl_id = clusters(to_cells(d_idle))

print('clusters across switch (cells):', cl_sw[:25], 'total px:', int(d_move.sum()))
print('EXCESS beyond idle (cells):', cl_ex[:30], 'total px:', int(excess.sum()))
print('idle control clusters (cells):', cl_id[:15], 'total px:', int(d_idle.sum()))

# strict strobe-red detector (excludes amber: needs g,b < 0.5r with r-g > 80)
for name, p in frames.items():
    a = load(p)
    r, g, b = a[..., 0].astype(int), a[..., 1].astype(int), a[..., 2].astype(int)
    strobe = (r > 100) & (g < 0.5*r) & (b < 0.5*r) & ((r - g) > 80)
    print(name, 'strobe_px:', int(strobe.sum()))
"}

