S = '.build/shots/'
P = {n: S + n + '.png' for n in
     ['p_strobe_on', 'p_strobe_off', 'p_anim', 'p_orbit_a', 'p_orbit_b', 'p_form_vee', 'p_drag']}

def clusters_info(mask, min_px=20):
    from collections import deque
    m8 = to_cells(mask, s=8, frac=0.1)
    seen = np.zeros_like(m8, bool)
    out = []
    ys, xs = np.nonzero(m8)
    for y0, x0 in zip(ys, xs):
        if seen[y0, x0]:
            continue
        q = deque([(y0, x0)]); seen[y0, x0] = True
        pts = []
        while q:
            y, x = q.popleft(); pts.append((y, x))
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < m8.shape[0] and 0 <= nx < m8.shape[1] and m8[ny, nx] and not seen[ny, nx]:
                        seen[ny, nx] = True; q.append((ny, nx))
        px = int(mask[[slice(y*8, y*8+8) for y, _ in pts], :].sum()) if False else len(pts) * 8 * 8
        if px >= min_px:
            ys2 = [p[0]*8+4 for p in pts]; xs2 = [p[1]*8+4 for p in pts]
            out.append({'px~': px, 'bbox_y': (min(ys2), max(ys2)), 'bbox_x': (min(xs2), max(xs2))})
    return sorted(out, key=lambda d: -d['px~'])[:12]

def changed(p1, p2, thr):
    a, b = load(p1).mean(2), load(p2).mean(2)
    return np.abs(a - b) > thr

print('== strobe_on vs strobe_off (thr 8) ==')
for c in clusters_info(changed(P['p_strobe_on'], P['p_strobe_off'], 8), 30):
    print(c)

print('== idle pair: ANY delta>2 region count ==')
m = changed(P['p_orbit_a'], P['p_orbit_b'], 2)
print('px>2:', int(m.sum()), 'of', m.size)
for c in clusters_info(m, 30):
    print(c)

print('== formation switch (thr 25) ==')
for c in clusters_info(changed(P['p_orbit_b'], P['p_form_vee'], 25), 30):
    print(c)

