"""Throwaway: GL-level truth — readPixels + getError around drone geometry."""
import json, os
from pathlib import Path
from playwright.sync_api import sync_playwright

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
URL = 'file://' + os.path.join(ROOT, 'index.html')

def esc(s):
    return s.replace('</script', '<\\/script')
shell = Path(ROOT, '.build', 'shell.html').read_text()
Path(ROOT, 'index.html').write_text(
    shell.replace('/*__THREE__*/', esc(Path(ROOT, '.build', 'three.min.js').read_text()))
         .replace('/*__APP__*/', esc(Path(ROOT, '.build', 'app.js').read_text())))

with sync_playwright() as p:
    b = p.chromium.launch(channel='chrome', headless=True)
    pg = b.new_page(viewport={'width': 1280, 'height': 800})
    errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)[:300]))
    pg.clock.install()
    pg.goto(URL)
    pg.clock.run_for(200)
    pg.click('#btnCam')
    pg.clock.run_for(2600)

    out = pg.evaluate('''(() => {
      const dbg = window.__dbg, r = dbg.renderer, gl = r.getContext();
      const res = {};

      // stage drone 0 dead-center in front of the manual-orbit camera
      dbg.drones[0].group.position.set(2, 12, 18);
      dbg.drones[0].group.visible = true;

      function frame() {
        r.render(dbg.scene, dbg.camera);
        const size = new THREE.Vector2();
        r.getSize(size);
        const v = new THREE.Vector3().copy(dbg.drones[0].group.position).project(dbg.camera);
        const cx = Math.round((v.x * 0.5 + 0.5) * size.x);
        const cy = Math.round((-v.y * 0.5 + 0.5) * size.y);
        const px = [];
        for (const [dx, dy] of [[0,0],[6,0],[-6,0],[0,6],[0,-6],[12,12],[-12,-12]]) {
          const q = new Uint8Array(4);
          gl.readPixels(cx+dx, cy+dy, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, q);
          px.push(Array.from(q));
        }
        // control sample far from the drone (top-left wall area)
        const ctl = new Uint8Array(4);
        gl.readPixels(30, 30, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, ctl);
        return {cx, cy, px, ctl: Array.from(ctl), err: gl.getError()};
      }

      res['as_is'] = frame();

      // now force bright red, disable fog — if pixels still don't change it's rasterization
      dbg.scene.fog = null;
      dbg.drones[0].group.traverse(o => {
        if (o.material) {
          o.material.color.setRGB(3, 0, 0);
          o.material.opacity = 1;
          o.material.transparent = false;
          o.material.fog = false;
          o.material.depthTest = false;
          o.material.needsUpdate = true;
        }
      });
      res['forced_red_nofog_nodepth'] = frame();

      // sanity: does a known-visible object change the framebuffer? brighten the door glow huge
      res['gl_error_after'] = gl.getError();
      res['drone_matrix'] = dbg.drones[0].group.matrixWorld.elements.map(x => +x.toFixed(2));
      res['hull_matrix'] = dbg.drones[0].group.children[0].matrixWorld.elements.map(x => +x.toFixed(2));
      res['hull_geom_bbox'] = (() => {
        const g = dbg.drones[0].group.children[0].geometry;
        g.computeBoundingBox();
        return [g.boundingBox.min.toArray(), g.boundingBox.max.toArray()];
      })();
      return res;
    })()''')
    print(json.dumps(out, indent=1))
    print('pageerrors:', errs)
    b.close()
EOF
