import json, os
from pathlib import Path
from playwright.sync_api import sync_playwright

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
URL = 'file://' + os.path.join(ROOT, 'index.html')

def esc(s):
    return s.replace('</script', '<\\/script')
shell = Path(ROOT, '.build', 'shell.html').read_text()
Path(ROOT, 'index.html').write_text(
    shell.replace('/*__THREE__*/', esc(Path(ROOT, '.build', 'three.min.js').read_text()))
         .replace('/*__APP__*/', esc(Path(ROOT, '.build', 'app.js').read_text())))

with sync_playwright() as p:
    b = p.chromium.launch(channel='chrome', headless=True)
    pg = b.new_page(viewport={'width': 1280, 'height': 800})
    errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)[:300]))
    pg.clock.install()
    pg.goto(URL)
    pg.clock.run_for(200)
    pg.click('#btnCam')
    pg.clock.run_for(2600)

    out = pg.evaluate('''(() => {
      const dbg = window.__dbg, r = dbg.renderer, gl = r.getContext();
      const res = { context_lost: gl.isContextLost() };

      dbg.drones[0].group.position.set(2, 12, 18);
      dbg.drones[0].group.visible = true;

      // fresh control mesh right next to the drone
      const ctrl = new THREE.Mesh(
        new THREE.BoxGeometry(1.2, 1.2, 1.2),
        new THREE.MeshBasicMaterial({ color: 0xff00ff }));
      ctrl.position.set(4.2, 12, 18);
      dbg.scene.add(ctrl);

      function probe(tag) {
        r.render(dbg.scene, dbg.camera);
        const size = new THREE.Vector2(); r.getSize(size);
        function sample(world) {
          const v = new THREE.Vector3().copy(world).project(dbg.camera);
          const cx = Math.round((v.x * 0.5 + 0.5) * size.x);
          const cy = Math.round((-v.y * 0.5 + 0.5) * size.y);
          const q = new Uint8Array(4);
          gl.readPixels(cx, cy, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, q);
          return { at: [cx, cy], rgba: Array.from(q) };
        }
        res[tag] = {
          drone: sample(dbg.drones[0].group.position),
          ctrl: sample(ctrl.position),
          calls: r.info.render.calls, tris: r.info.render.triangles
        };
      }

      probe('fresh_box_vs_drone');

      // force everything (incl drone) through one override program
      dbg.scene.overrideMaterial = new THREE.MeshBasicMaterial({ color: 0x00ff44 });
      probe('override_material');
      dbg.scene.overrideMaterial = null;

      // drone-only: replace all children with a brand-new box inside the drone group
      const old = dbg.drones[0].group.children.slice();
      old.forEach(c => dbg.drones[0].group.remove(c));
      const fresh = new THREE.Mesh(new THREE.BoxGeometry(1.2, 1.2, 1.2),
        new THREE.MeshBasicMaterial({ color: 0xffcc00 }));
      dbg.drones[0].group.add(fresh);
      probe('fresh_box_inside_drone_group');

      res['context_lost_end'] = gl.isContextLost();
      res['err_end'] = gl.getError();
      return res;
    })()''')
    print(json.dumps(out, indent=1))
    print('pageerrors:', errs)
    b.close()
