"""Throwaway: what object actually occupies the drone's pixel? (raycast truth)"""
import json, os
from pathlib import Path
from playwright.sync_api import sync_playwright

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
URL = 'file://' + os.path.join(ROOT, 'index.html')

def esc(s):
    return s.replace('</script', '<\\/script')
shell = Path(ROOT, '.build', 'shell.html').read_text()
Path(ROOT, 'index.html').write_text(
    shell.replace('/*__THREE__*/', esc(Path(ROOT, '.build', 'three.min.js').read_text()))
         .replace('/*__APP__*/', esc(Path(ROOT, '.build', 'app.js').read_text())))

with sync_playwright() as p:
    b = p.chromium.launch(channel='chrome', headless=True)
    pg = b.new_page(viewport={'width': 1280, 'height': 800})
    errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)[:300]))
    pg.clock.install()
    pg.goto(URL)
    pg.clock.run_for(200)
    pg.click('#btnCam')
    pg.clock.run_for(2600)

    out = pg.evaluate('''(() => {
      const dbg = window.__dbg, r = dbg.renderer, gl = r.getContext();
      const res = {};

      dbg.drones[0].group.position.set(2, 12, 18);
      const target = dbg.drones[0].group.position.clone();
      const v = target.clone().project(dbg.camera);
      const ndc = new THREE.Vector2(v.x, v.y);

      const ray = new THREE.Raycaster();
      ray.setFromCamera(ndc, dbg.camera);
      const hits = ray.intersectObjects(dbg.scene.children, true);
      res['hits_at_drone_pixel'] = hits.slice(0, 8).map(h => ({
        dist: +h.distance.toFixed(2),
        type: h.object.type,
        geom: h.object.geometry ? h.object.geometry.type : null,
        mat: h.object.material ? [h.object.material.type,
             h.object.material.transparent, h.object.material.opacity,
             h.object.material.depthWrite, h.object.material.side] : null,
        parent: h.object.parent ? h.object.parent.type : null,
        pos: h.object.getWorldPosition(new THREE.Vector3()).toArray().map(x => +x.toFixed(1))
      }));
      res['drone_target_dist'] = +target.clone().sub(dbg.camera.position).length().toFixed(2);
      res['num_hits'] = hits.length;

      // hide the drone group and re-raycast: who is BEHIND it?
      dbg.drones[0].group.visible = false;
      const hits2 = ray.intersectObjects(dbg.scene.children, true);
      res['hits_without_drone'] = hits2.slice(0, 5).map(h => ({
        dist: +h.distance.toFixed(2), type: h.object.type,
        geom: h.object.geometry ? h.object.geometry.type : null,
        transparent: h.object.material ? h.object.material.transparent : null,
        opacity: h.object.material ? h.object.material.opacity : null
      }));
      dbg.drones[0].group.visible = true;

      // nuke test: only the drone group left (plus a light), forced opaque yellow
      const keep = new Set();
      dbg.drones[0].group.traverse(o => {
        keep.add(o);
        if (o.material) {
          o.material.color.setRGB(3, 2, 0);
          o.material.transparent = false;
          o.material.opacity = 1;
          o.material.depthWrite = true;
          o.material.depthTest = true;
          o.material.needsUpdate = true;
        }
      });
      const hidden = [];
      dbg.scene.traverse(o => {
        if (o.isMesh || o.isSprite) {
          if (!keep.has(o)) { hidden.push(o); o.visible = false; }
        }
      });
      r.render(dbg.scene, dbg.camera);
      const size = new THREE.Vector2(); r.getSize(size);
      const px = new Uint8Array(4);
      const cx = Math.round((v.x * 0.5 + 0.5) * size.x);
      const cy = Math.round((-v.y * 0.5 + 0.5) * size.y);
      gl.readPixels(cx, cy, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
      res['nuke_test_pixel'] = { at: [cx, cy], rgba: Array.from(px), hidden_count: hidden.length,
                                 calls: r.info.render.calls };

