import json, os
from pathlib import Path
from playwright.sync_api import sync_playwright

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
URL = 'file://' + os.path.join(ROOT, 'index.html')

def esc(s):
    return s.replace('</script', '<\\/script')
shell = Path(ROOT, '.build', 'shell.html').read_text()
Path(ROOT, 'index.html').write_text(
    shell.replace('/*__THREE__*/', esc(Path(ROOT, '.build', 'three.min.js').read_text()))
         .replace('/*__APP__*/', esc(Path(ROOT, '.build', 'app.js').read_text())))

with sync_playwright() as p:
    b = p.chromium.launch(channel='chrome', headless=True)
    pg = b.new_page(viewport={'width': 1280, 'height': 800})
    errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)[:300]))
    pg.clock.install()
    pg.goto(URL)
    pg.clock.run_for(200)
    pg.click('#btnCam')
    pg.clock.run_for(2600)

    out = pg.evaluate('''(() => {
      const dbg = window.__dbg, r = dbg.renderer, gl = r.getContext();
      const res = {};
      const g0 = dbg.drones[0].group;
      const hullGeo = g0.children[0].geometry;
      const hullMat = g0.children[0].material;
      res['hull_geo'] = {
        pos_count: hullGeo.attributes.position.count,
        index: hullGeo.index ? hullGeo.index.count : null,
        drawRange: [hullGeo.drawRange.start, hullGeo.drawRange.count],
        attrs: Object.keys(hullGeo.attributes)
      };
      res['hull_mat'] = {
        type: hullMat.type, visible: hullMat.visible,
        transparent: hullMat.transparent, opacity: hullMat.opacity,
        side: hullMat.side, depthTest: hullMat.depthTest, depthWrite: hullMat.depthWrite,
        colorWrite: hullMat.colorWrite, blending: hullMat.blending,
        skinning: hullMat.skinning, morphTargets: hullMat.morphTargets,
        vertexColors: hullMat.vertexColors
      };

      // park all drones far away; camera looks at empty space in the hangar
      dbg.drones.forEach(d => { d.group.visible = false; });

      const poolMat = dbg.scene.children.find(o => o.isMesh && o.material.map && o.material.blending === 2);
      const cases = [
        ['fresh_geo_fresh_mat', new THREE.BoxGeometry(1.4, 1.4, 1.4), new THREE.MeshBasicMaterial({ color: 0xff00ff })],
        ['hull_geo_fresh_mat',  hullGeo,                            new THREE.MeshBasicMaterial({ color: 0x00ff00 })],
        ['fresh_geo_hull_mat',  new THREE.BoxGeometry(1.4, 1.4, 1.4), hullMat],
        ['hull_geo_hull_mat',   hullGeo,                            hullMat],
      ];
      const added = [];
      const saved = dbg.drones[0].group.visible;
      cases.forEach((c, i) => {
        const m = new THREE.Mesh(c[1], c[2]);
        m.position.set(-6 + i * 4, 12, 18);
        dbg.scene.add(m);          // scene level first
        added.push(m);
      });

      function sampleAll(tag) {
        r.render(dbg.scene, dbg.camera);
        const size = new THREE.Vector2(); r.getSize(size);
        res[tag] = added.map(m => {
          const v = m.position.clone().project(dbg.camera);
          const cx = Math.round((v.x * 0.5 + 0.5) * size.x);
          const cy = Math.round((-v.y * 0.5 + 0.5) * size.y);
          const q = new Uint8Array(4);
          gl.readPixels(cx, cy, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, q);
          return [m.geometry === hullGeo ? 'hullGeo' : 'boxGeo', Array.from(q).slice(0, 3), [cx, cy]];
        });
      }

      dbg.scene.updateMatrixWorld(true);
      sampleAll('scene_level');

      // move the same meshes under the drone group and re-sample
      added.forEach(m => { dbg.scene.remove(m); g0.add(m); });
      g0.visible = true;
      g0.position.set(0, 0, 0);
      dbg.scene.updateMatrixWorld(true);
      sampleAll('inside_drone_group');

      res['err'] = gl.getError();
      res['calls'] = r.info.render.calls;
      return res;
    })()''')
    print(json.dumps(out, indent=1))
    print('pageerrors:', errs)
    b.close()
